Most elkészítem a teljes integrációt az Exa AI keresővel a Flask alkalmazásodba. Az Exa AI egy neurális keresőmotor, amelyet kifejezetten AI alkalmazásokhoz terveztek, és támogatja az akár 100 találat lekérését query-nként különféle szűrőkkel.[1][2][3][4]

## Az Exa AI Keresés Integrálása GLM 4.7-tel

Az Exa AI és a GLM 4.7 kombinációja lehetővé teszi, hogy az AI autonóm módon döntsön a keresés használatáról és optimalizálja a query-ket. A GLM-4.7 natívan támogatja a function calling-ot, amely lehetővé teszi számára, hogy strukturált formában hívjon meg külső eszközöket.[5][6][4]

### Telepítendő Csomagok

```bash
pip install exa-py cerebras python-dotenv flask
```

### Környezeti Változók (.env)

```env
CEREBRAS_API_KEY=your_cerebras_api_key_here
EXA_API_KEY=your_exa_api_key_here
```

### Továbbfejlesztett Flask Alkalmazás Function Calling-gal

```python
import os
import json
from flask import Flask, Response, request, send_from_directory
from cerebras.cloud.sdk import Cerebras
from exa_py import Exa
from dotenv import load_dotenv

# Környezeti változók betöltése
load_dotenv()

app = Flask(__name__, static_folder=".")

# Kliensek inicializálása
cerebras_client = Cerebras(api_key=os.environ.get("CEREBRAS_API_KEY"))
exa_client = Exa(os.environ.get("EXA_API_KEY"))

# Exa keresési funkció definiálása
def search_web_exa(queries, num_results_per_query=100, search_type="auto", 
                   use_filters=True, include_domains=None, exclude_domains=None,
                   start_published_date=None, end_published_date=None,
                   category=None, include_text=None, exclude_text=None):
    """
    Webes keresés végrehajtása az Exa AI-val

    Args:
        queries: Lista a keresési query-kről (max 10)
        num_results_per_query: Találatok száma query-nként (max 100)
        search_type: "auto", "neural", "fast", vagy "deep"
        use_filters: Szűrők használata
        include_domains: Csak ezekről a domain-ekről keressen
        exclude_domains: Ezeket a domain-eket zárja ki
        start_published_date: Csak ennél újabb cikkek
        end_published_date: Csak ennél régebbi cikkek
        category: Kategória szűrő (company, research paper, news, github, tweet, etc.)
        include_text: Ezeket a szövegeket tartalmaznia kell
        exclude_text: Ezeket a szövegeket nem tartalmazhatja
    """
    all_results = []

    # Maximum 10 query-t engedélyezünk
    queries = queries[:10]

    for query in queries:
        try:
            # Keresési paraméterek összeállítása
            search_params = {
                "query": query,
                "num_results": num_results_per_query,
                "type": search_type,
                "text": True,  # Teljes szöveg lekérése
                "highlights": True  # Kiemelt részek lekérése
            }

            # Opcionális szűrők hozzáadása ha use_filters=True
            if use_filters:
                if include_domains:
                    search_params["include_domains"] = include_domains
                if exclude_domains:
                    search_params["exclude_domains"] = exclude_domains
                if start_published_date:
                    search_params["start_published_date"] = start_published_date
                if end_published_date:
                    search_params["end_published_date"] = end_published_date
                if category:
                    search_params["category"] = category
                if include_text:
                    search_params["include_text"] = include_text
                if exclude_text:
                    search_params["exclude_text"] = exclude_text

            # Keresés végrehajtása
            result = exa_client.search_and_contents(**search_params)

            # Eredmények formázása
            for item in result.results:
                formatted_result = {
                    "query": query,
                    "title": item.title,
                    "url": item.url,
                    "published_date": item.published_date if hasattr(item, 'published_date') else None,
                    "author": item.author if hasattr(item, 'author') else None,
                    "text": item.text[:2000] if hasattr(item, 'text') and item.text else "",  # Első 2000 karakter
                    "highlights": item.highlights[:3] if hasattr(item, 'highlights') else [],  # Első 3 highlight
                }
                all_results.append(formatted_result)

        except Exception as e:
            all_results.append({
                "query": query,
                "error": str(e)
            })

    return {
        "total_results": len(all_results),
        "results": all_results
    }

# Tool definíció a GLM 4.7 számára
TOOLS = [
    {
        "type": "function",
        "function": {
            "name": "search_web_exa",
            "description": """Webes keresés végrehajtása az Exa AI neurális keresőmotorral. 
            Ez egy speciális AI-alapú keresőmotor, amely szemantikus keresést végez.
            Használd ezt akkor, ha aktuális információkra, friss hírekre, kutatási eredményekre van szükség.
            Maximum 10 különböző query-t adhatsz meg, mindegyik max 100 találatot ad vissza.
            Automatikusan optimalizáld a query-ket a legjobb eredmények érdekében!""",
            "parameters": {
                "type": "object",
                "properties": {
                    "queries": {
                        "type": "array",
                        "items": {"type": "string"},
                        "description": "Keresési query-k listája (maximum 10). Minden query-t optimalizálj a legjobb találatok érdekében.",
                        "maxItems": 10
                    },
                    "num_results_per_query": {
                        "type": "integer",
                        "description": "Találatok száma query-nként (1-100). Alapértelmezett: 100",
                        "default": 100,
                        "minimum": 1,
                        "maximum": 100
                    },
                    "search_type": {
                        "type": "string",
                        "enum": ["auto", "neural", "fast", "deep"],
                        "description": "Keresés típusa. 'auto': automatikus választás, 'neural': neurális szemantikus keresés, 'fast': gyors keresés, 'deep': mélyreható keresés több variációval",
                        "default": "auto"
                    },
                    "use_filters": {
                        "type": "boolean",
                        "description": "Szűrők használata (domain, dátum, kategória, stb.)",
                        "default": True
                    },
                    "include_domains": {
                        "type": "array",
                        "items": {"type": "string"},
                        "description": "Csak ezekről a domain-ekről keressen (pl. ['wikipedia.org', 'arxiv.org'])"
                    },
                    "exclude_domains": {
                        "type": "array",
                        "items": {"type": "string"},
                        "description": "Ezeket a domain-eket zárja ki a keresésből"
                    },
                    "start_published_date": {
                        "type": "string",
                        "description": "Csak ennél újabb publikációkat keressen (YYYY-MM-DD formátum)"
                    },
                    "end_published_date": {
                        "type": "string",
                        "description": "Csak ennél régebbi publikációkat keressen (YYYY-MM-DD formátum)"
                    },
                    "category": {
                        "type": "string",
                        "enum": ["company", "research paper", "news", "github", "tweet", "personal site", "pdf", "financial report", "people"],
                        "description": "Kategória szűrő a kereséshez"
                    },
                    "include_text": {
                        "type": "array",
                        "items": {"type": "string"},
                        "description": "Az eredményeknek tartalmazniuk kell ezeket a szövegrészleteket (max 1 elem, max 5 szó)",
                        "maxItems": 1
                    },
                    "exclude_text": {
                        "type": "array",
                        "items": {"type": "string"},
                        "description": "Az eredmények nem tartalmazhatják ezeket a szövegrészleteket (max 1 elem, max 5 szó)",
                        "maxItems": 1
                    }
                },
                "required": ["queries"]
            }
        }
    }
]

@app.route("/")
def index():
    return send_from_directory(".", "index.html")

@app.route("/chat", methods=["POST"])
def chat():
    data = request.get_json()
    user_message = data.get("message", "")
    enable_search = data.get("enable_search", False)

    def generate():
        messages = [
            {
                "role": "system",
                "content": """Mindig magyarul válaszolj, tökéletes változatos természetes anyanyelvi magyarral.

Ha a keresés engedélyezve van és a felhasználó kérdése aktuális információkat, friss adatokat, 
kutatási eredményeket vagy bármilyen webes információt igényel, akkor AUTOMATIKUSAN használd 
a search_web_exa eszközt!

Amikor keresést végzel:
1. Készíts optimalizált keresési query-ket (maximum 10-et)
2. Használj megfelelő szűrőket a legjobb eredmények érdekében
3. Állítsd be a találatok számát query-nként (max 100)
4. Válaszd ki a legmegfelelőbb search_type-ot (auto, neural, fast, deep)
5. Alkalmazz dátum, domain vagy kategória szűrőket ha releváns

Az eredményeket felhasználva adj átfogó, részletes választ a felhasználó kérdésére.
Hivatkozz a forrásokra (URL-ek) a válaszodban!"""
            },
            {
                "role": "user",
                "content": user_message
            }
        ]

        # Ha a keresés engedélyezve van, hozzáadjuk a tool-okat
        if enable_search:
            stream = cerebras_client.chat.completions.create(
                messages=messages,
                model="zai-glm-4.7",
                stream=True,
                max_completion_tokens=65000,
                temperature=1,
                top_p=0.95,
                disable_reasoning=False,
                reasoning_format="parsed",
                clear_thinking=False,
                tools=TOOLS,
                tool_choice="auto",  # Az AI dönt a tool használatról
                parallel_tool_calls=True  # Párhuzamos tool hívások engedélyezése
            )
        else:
            # Keresés nélküli mód - eredeti működés
            stream = cerebras_client.chat.completions.create(
                messages=messages,
                model="zai-glm-4.7",
                stream=True,
                max_completion_tokens=65000,
                temperature=1,
                top_p=0.95,
                disable_reasoning=False,
                reasoning_format="parsed",
                clear_thinking=False
            )

        tool_calls_buffer = {}

        for chunk in stream:
            choices = getattr(chunk, "choices", [])
            if isinstance(choices, list) and len(choices) > 0:
                choice = choices[0]
                delta = getattr(choice, "delta", None)

                if delta:
                    # Reasoning tartalom kezelése
                    reasoning = getattr(delta, "reasoning", None)
                    if reasoning:
                        payload = json.dumps({"type": "reasoning", "content": reasoning}, ensure_ascii=False)
                        yield f"data: {payload}\n\n"

                    # Tool calls kezelése
                    tool_calls = getattr(delta, "tool_calls", None)
                    if tool_calls:
                        for tool_call in tool_calls:
                            idx = getattr(tool_call, "index", 0)
                            if idx not in tool_calls_buffer:
                                tool_calls_buffer[idx] = {
                                    "id": getattr(tool_call, "id", ""),
                                    "type": getattr(tool_call, "type", "function"),
                                    "function": {
                                        "name": "",
                                        "arguments": ""
                                    }
                                }

                            function = getattr(tool_call, "function", None)
                            if function:
                                name = getattr(function, "name", None)
                                if name:
                                    tool_calls_buffer[idx]["function"]["name"] = name

                                arguments = getattr(function, "arguments", None)
                                if arguments:
                                    tool_calls_buffer[idx]["function"]["arguments"] += arguments

                    # Normál tartalom kezelése
                    content = getattr(delta, "content", None)
                    if content:
                        payload = json.dumps({"type": "content", "content": content}, ensure_ascii=False)
                        yield f"data: {payload}\n\n"

                # Ha finish_reason == "tool_calls", végrehajtjuk a tool-okat
                finish_reason = getattr(choice, "finish_reason", None)
                if finish_reason == "tool_calls" and tool_calls_buffer:
                    # Tool calls végrehajtása
                    payload = json.dumps({
                        "type": "info", 
                        "content": f"\n\n🔍 Keresés végrehajtása... ({len(tool_calls_buffer)} keresési kérés)\n\n"
                    }, ensure_ascii=False)
                    yield f"data: {payload}\n\n"

                    tool_results = []
                    for idx, tool_call in tool_calls_buffer.items():
                        function_name = tool_call["function"]["name"]
                        function_args = json.loads(tool_call["function"]["arguments"])

                        if function_name == "search_web_exa":
                            # Keresés végrehajtása
                            search_result = search_web_exa(**function_args)
                            tool_results.append({
                                "tool_call_id": tool_call["id"],
                                "role": "tool",
                                "name": function_name,
                                "content": json.dumps(search_result, ensure_ascii=False)
                            })

                            # Információ a keresésről
                            queries = function_args.get("queries", [])
                            total = search_result.get("total_results", 0)
                            info_msg = f"✅ Keresés befejezve: {len(queries)} query, {total} találat\n\n"
                            payload = json.dumps({"type": "info", "content": info_msg}, ensure_ascii=False)
                            yield f"data: {payload}\n\n"

                    # Folytatjuk a beszélgetést a tool eredményekkel
                    messages.extend(tool_results)

                    # Új completion a tool eredményekkel
                    second_stream = cerebras_client.chat.completions.create(
                        messages=messages,
                        model="zai-glm-4.7",
                        stream=True,
                        max_completion_tokens=65000,
                        temperature=1,
                        top_p=0.95,
                        disable_reasoning=False,
                        reasoning_format="parsed",
                        clear_thinking=False
                    )

                    for second_chunk in second_stream:
                        second_choices = getattr(second_chunk, "choices", [])
                        if isinstance(second_choices, list) and len(second_choices) > 0:
                            second_choice = second_choices[0]
                            second_delta = getattr(second_choice, "delta", None)

                            if second_delta:
                                reasoning = getattr(second_delta, "reasoning", None)
                                if reasoning:
                                    payload = json.dumps({"type": "reasoning", "content": reasoning}, ensure_ascii=False)
                                    yield f"data: {payload}\n\n"

                                content = getattr(second_delta, "content", None)
                                if content:
                                    payload = json.dumps({"type": "content", "content": content}, ensure_ascii=False)
                                    yield f"data: {payload}\n\n"

                    tool_calls_buffer.clear()

        yield "data: [DONE]\n\n"

    return Response(generate(), mimetype="text/event-stream")

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000, debug=True)
```

