                        "maxItems": 10
                    },
                    "num_results_per_query": {
                        "type": "integer",
                        "description": "Találatok száma query-nként (1-100). Alapértelmezett: 100",
                        "default": 100,
                        "minimum": 1,
                        "maximum": 100
                    },
