                        "type": "array",
                        "items": {"type": "string"},
                        "description": "Csak ezekről a domain-ekről keressen"
                    },
                    "exclude_domains": {
                        "type": "array",
                        "items": {"type": "string"},
                        "description": "Ezeket a domain-eket zárja ki a keresésből"
                    },
                    "start_published_date": {
                        "type": "string",
                        "description": "Csak ennél újabb publikációkat keressen (YYYY-MM-DD formátum)"
                    },
                    "end_published_date": {
                        "type": "string",
                        "description": "Csak ennél régebbi publikációkat keressen (YYYY-MM-DD formátum)"
                    },
                    "category": {
                        "type": "string",
                        "enum": ["company", "research paper", "news", "github", "tweet", "personal site", "pdf", "financial report", "people"],
                        "description": "Kategória szűrő a kereséshez"
                    },
                    "include_text": {
                        "type": "array",
                        "items": {"type": "string"},
                        "description": "Az eredményeknek tartalmazniuk kell ezeket a szövegrészleteket (max 1 elem, max 5 szó)",
                        "maxItems": 1
                    },
                    "exclude_text": {
