container.className = 'msg-container msg-assistant';
const bubble = document.createElement('div');
bubble.className = 'bubble bubble-assistant';
container.appendChild(bubble);
ui.chat.appendChild(container);
ui.chat.scrollTop = ui.chat.scrollHeight;
let fullText = '';
state.controller = new AbortController();
const timeoutId = setTimeout(() => state.controller.abort(), 45000);
try {
const response = await fetch(API_URL + '/chat', {
method: 'POST',
headers: {'Content-Type': 'application/json'},
body: JSON.stringify({
message: userQuery,
sessionid: sessionId,
usedeep: false,
enable_search: ui.searchToggle.checked
}),
signal: state.controller.signal
});
clearTimeout(timeoutId);
if (!response.ok) throw new Error('HTTP ' + response.status);
const reader = response.body.getReader();
const decoder = new TextDecoder();
let buffer = '';
try {
while (true) {
const {done, value} = await reader.read();
if (done) break;
buffer += decoder.decode(value, {stream: true});
const lines = buffer.split('\n');
buffer = lines.pop() || '';
for (const line of lines) {
if (line.startsWith('data: ')) {
try {
const data = JSON.parse(line.slice(6));
if (data.content) {
fullText += data.content;
bubble.innerHTML = formatMessage(fullText);
if (fullText.length % 50 === 0) {
ui.chat.scrollTo({top: ui.chat.scrollHeight, behavior: 'auto'});
}
}
if (data.error) {
fullText += 'Hiba: ' + data.content;
}
} catch (e) {
}
}
}
}
} finally {
reader.cancel();
}
} catch (err) {
fullText = err.name === 'AbortError' ? 'Időtúllépés' : 'Hiba történt';
bubble.innerText = fullText;
}
conversationHistory.push({role: 'assistant', content: fullText});
container.remove();
appendMessage('assistant', fullText);
setBusy(false);
state.controller = null;
}
function drawDandelion(id) {
const canvas = document.getElementById('c-' + id);
if (!canvas) return;
const ctx = canvas.getContext('2d');
const dpr = window.devicePixelRatio || 1;
canvas.width = 80 * dpr;
canvas.height = 80 * dpr;
ctx.scale(dpr, dpr);
const pts = [];
for (let i = 0; i < 150; i++) {
const phi = Math.acos(1 - 2 * (i + 0.5) / 150);
const theta = Math.PI * (1 + Math.sqrt(5)) * i;
pts.push({
ox: Math.cos(theta) * Math.sin(phi) * 28,
oy: Math.sin(theta) * Math.sin(phi) * 28,
oz: Math.cos(phi) * 28
});
}
let rot = 0;
let time = 0;
function frame() {
if (!document.getElementById('c-' + id)) return;
ctx.clearRect(0, 0, 80, 80);
rot += 0.01;
time += 0.03;
const pulse = 1 + Math.sin(time) * 0.05;
pts.forEach(p => {
let x = p.ox * pulse * Math.cos(rot) - p.oz * pulse * Math.sin(rot);
let z = p.ox * pulse * Math.sin(rot) + p.oz * pulse * Math.cos(rot);
const scale = 100 / (100 + z);
const alpha = Math.max(0.1, (z + 30) / 60);
ctx.fillStyle = 'rgba(255, 18, 126, ' + alpha + ')';
ctx.beginPath();
ctx.arc(40 + x * scale, 40 + p.oy * pulse * scale, 0.8 * scale, 0, Math.PI * 2);
ctx.fill();
});
state.animationFrameId = requestAnimationFrame(frame);
}
frame();
}
