Az alábbi kódokban eltávolításra került a fejlécből az Exa keresés kapcsolója és a Deep gomb, helyettük az input sávban egy kör alakú plusz ikon jelent meg, amely felnyíló menüben tartalmazza a webes keresés be/ki kapcsolását, miközben a backend változatlanul támogatja az Exa-alapú keresést az `enable_search` flagen keresztül. A modell gondolatmenete (reasoning) mostantól alapértelmezetten rejtve marad, de minden asszisztens üzenethez külön felugró, gombbal nyitható/zárható „Gondolatmenet” panel tartozik, és a kódblokkok mind a felhasználói, mind az asszisztens üzenetekben automatikusan összecsukva jelennek meg, fejléccel (nyelv, sorok száma, másolás, nyit/zár). A Flask backend az `index-2.html` frontendet szolgálja ki, streaming SSE-t használ, és production-ready módon kezeli a GLM 4.7-es modell tool hívásait az Exa-kereséshez.[1][2][3]

## Backend szerver (app.py)

```python
import os
import json
from flask import Flask, Response, request, send_from_directory
from cerebras.cloud.sdk import Cerebras
from exa_py import Exa
from dotenv import load_dotenv

load_dotenv()

app = Flask(__name__, static_folder=".")

cerebras_client = Cerebras(api_key=os.environ.get("CEREBRAS_API_KEY"))
exa_client = Exa(os.environ.get("EXA_API_KEY"))


def search_web_exa(
    queries,
    num_results_per_query=100,
    search_type="auto",
    use_filters=True,
    include_domains=None,
    exclude_domains=None,
    start_published_date=None,
    end_published_date=None,
    category=None,
    include_text=None,
    exclude_text=None,
):
    all_results = []
    queries = queries[:10]

    for query in queries:
        try:
            search_params = {
                "query": query,
                "num_results": num_results_per_query,
                "type": search_type,
                "text": True,
                "highlights": True,
            }

            if use_filters:
                if include_domains:
                    search_params["include_domains"] = include_domains
                if exclude_domains:
                    search_params["exclude_domains"] = exclude_domains
                if start_published_date:
                    search_params["start_published_date"] = start_published_date
                if end_published_date:
                    search_params["end_published_date"] = end_published_date
                if category:
                    search_params["category"] = category
                if include_text:
                    search_params["include_text"] = include_text
                if exclude_text:
                    search_params["exclude_text"] = exclude_text

            result = exa_client.search_and_contents(**search_params)

            for item in result.results:
                formatted_result = {
                    "query": query,
                    "title": item.title,
                    "url": item.url,
                    "published_date": item.published_date if hasattr(item, "published_date") else None,
                    "author": item.author if hasattr(item, "author") else None,
                    "text": item.text[:2000] if hasattr(item, "text") and item.text else "",
                    "highlights": item.highlights[:3] if hasattr(item, "highlights") else [],
                }
                all_results.append(formatted_result)

        except Exception as e:
            all_results.append(
                {
                    "query": query,
                    "error": str(e),
                }
            )

    return {
        "total_results": len(all_results),
        "results": all_results,
    }


TOOLS = [
    {
        "type": "function",
        "function": {
