@app.route("/")
def index():
    return send_from_directory(".", "index-2.html")


@app.route("/chat", methods=["POST"])
def chat():
    data = request.get_json()
    user_message = data.get("message", "")
    enable_search = data.get("enable_search", False)

    def generate():
        messages = [
            {
                "role": "system",
                "content": "Mindig magyarul válaszolj, tökéletes, változatos, természetes anyanyelvi magyarral. Ha a keresés engedélyezve van, és a felhasználó kérdése aktuális információkat, friss adatokat, kutatási eredményeket vagy bármilyen webes információt igényel, akkor automatikusan használd a search_web_exa eszközt. Amikor keresést végzel, készíts optimalizált keresési query-ket (maximum 10-et), használj megfelelő szűrőket, állítsd be a találatok számát query-nként (legfeljebb 100), válaszd ki a legmegfelelőbb search_type-ot (auto, neural, fast, deep), és szükség esetén alkalmazz dátum, domain vagy kategória szűrőket. Az eredményeket felhasználva adj átfogó, részletes választ a felhasználó kérdésére, és hivatkozz a releváns URL-ekre.",
            },
            {
                "role": "user",
                "content": user_message,
            },
        ]

        if enable_search:
            stream = cerebras_client.chat.completions.create(
                messages=messages,
                model="zai-glm-4.7",
                stream=True,
                max_completion_tokens=65000,
                temperature=1,
                top_p=0.95,
                disable_reasoning=False,
                reasoning_format="parsed",
                clear_thinking=False,
                tools=TOOLS,
                tool_choice="auto",
                parallel_tool_calls=True,
            )
        else:
            stream = cerebras_client.chat.completions.create(
                messages=messages,
                model="zai-glm-4.7",
                stream=True,
                max_completion_tokens=65000,
                temperature=1,
                top_p=0.95,
                disable_reasoning=False,
                reasoning_format="parsed",
                clear_thinking=False,
            )

        tool_calls_buffer = {}

        for chunk in stream:
            choices = getattr(chunk, "choices", [])
            if isinstance(choices, list) and choices:
                choice = choices[0]
                delta = getattr(choice, "delta", None)

                if delta:
                    reasoning = getattr(delta, "reasoning", None)
                    if reasoning:
                        payload = json.dumps(
                            {
                                "type": "reasoning",
                                "content": reasoning,
                            },
                            ensure_ascii=False,
                        )
                        yield f"data: {payload}\n\n"

                    tool_calls = getattr(delta, "tool_calls", None)
                    if tool_calls:
                        for tool_call in tool_calls:
                            idx = getattr(tool_call, "index", 0)
                            if idx not in tool_calls_buffer:
                                tool_calls_buffer[idx] = {
                                    "id": getattr(tool_call, "id", ""),
                                    "type": getattr(tool_call, "type", "function"),
                                    "function": {
                                        "name": "",
                                        "arguments": "",
                                    },
                                }

                            function = getattr(tool_call, "function", None)
                            if function:
                                name = getattr(function, "name", None)
                                if name:
                                    tool_calls_buffer[idx]["function"]["name"] = name

                                arguments = getattr(function, "arguments", None)
                                if arguments:
                                    tool_calls_buffer[idx]["function"]["arguments"] += arguments

                    content = getattr(delta, "content", None)
                    if content:
                        payload = json.dumps(
                            {
                                "type": "content",
                                "content": content,
                            },
                            ensure_ascii=False,
                        )
                        yield f"data: {payload}\n\n"

                finish_reason = getattr(choice, "finish_reason", None)
                if finish_reason == "tool_calls" and tool_calls_buffer:
                    info_payload = json.dumps(
                        {
                            "type": "info",
                            "content": f"\n\nKeresés végrehajtása... ({len(tool_calls_buffer)} keresési kérés)\n\n",
                        },
                        ensure_ascii=False,
                    )
                    yield f"data: {info_payload}\n\n"

                    tool_results = []
                    for idx, tool_call in tool_calls_buffer.items():
                        function_name = tool_call["function"]["name"]
                        function_args = json.loads(tool_call["function"]["arguments"])

                        if function_name == "search_web_exa":
                            search_result = search_web_exa(**function_args)
                            tool_results.append(
                                {
                                    "tool_call_id": tool_call["id"],
                                    "role": "tool",
                                    "name": function_name,
                                    "content": json.dumps(search_result, ensure_ascii=False),
                                }
                            )
                            queries = function_args.get("queries", [])
                            total = search_result.get("total_results", 0)
                            info_msg = f"Keresés befejezve: {len(queries)} query, {total} találat\n\n"
                            done_payload = json.dumps(
                                {
                                    "type": "info",
                                    "content": info_msg,
                                },
                                ensure_ascii=False,
                            )
                            yield f"data: {done_payload}\n\n"

                    messages.extend(tool_results)

                    second_stream = cerebras_client.chat.completions.create(
                        messages=messages,
                        model="zai-glm-4.7",
                        stream=True,
                        max_completion_tokens=65000,
                        temperature=1,
                        top_p=0.95,
                        disable_reasoning=False,
                        reasoning_format="parsed",
                        clear_thinking=False,
                    )

                    for second_chunk in second_stream:
                        second_choices = getattr(second_chunk, "choices", [])
                        if isinstance(second_choices, list) and second_choices:
                            second_choice = second_choices[0]
                            second_delta = getattr(second_choice, "delta", None)

                            if second_delta:
                                second_reasoning = getattr(second_delta, "reasoning", None)
                                if second_reasoning:
                                    payload = json.dumps(
                                        {
                                            "type": "reasoning",
                                            "content": second_reasoning,
                                        },
                                        ensure_ascii=False,
                                    )
                                    yield f"data: {payload}\n\n"

                                second_content = getattr(second_delta, "content", None)
                                if second_content:
                                    payload = json.dumps(
                                        {
                                            "type": "content",
                                            "content": second_content,
                                        },
                                        ensure_ascii=False,
                                    )
                                    yield f"data: {payload}\n\n"

                    tool_calls_buffer.clear()

        yield "data: [DONE]\n\n"

    return Response(generate(), mimetype="text/event-stream")


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000, debug=True)
