--shade-95: #0d0107;
--shade-100: #000000;
--tint-10: #ff2a8b;
--tint-20: #ff4198;
--tint-30: #ff59a5;
--tint-40: #ff71b2;
--tint-50: #ff89bf;
--tint-60: #ffa0cb;
--tint-70: #ffb8d8;
--tint-80: #ffd0e5;
--tint-90: #ffe7f2;
--tint-100: #ffffff;
--bg-color: #19020d;
--surface-glass: rgba(51, 4, 25, 0.95);
--border-dim: #4c0526;
--text-main: #ffe7f2;
--text-muted: #ffa0cb;
--safe-top: env(safe-area-inset-top, 20px);
--safe-bottom: env(safe-area-inset-bottom, 20px);
--header-height: 50px;
--input-area-height: auto;
}
@font-face {
font-family: "SF Pro Display";
src: local("SF Pro Display"), local(".SFNSText-Regular"), local("Helvetica Neue"), sans-serif;
}
* {
box-sizing: border-box;
-webkit-tap-highlight-color: transparent;
font-family: -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text", "Helvetica Neue", sans-serif;
}
body {
background-color: var(--bg-color);
color: var(--tint-100);
margin: 0;
height: 100dvh;
width: 100%;
overflow: hidden;
position: fixed;
font-size: 13.5px;
overscroll-behavior: none;
}
.ambient-layer {
position: fixed;
inset: 0;
z-index: -1;
background: #000000;
overflow: hidden;
pointer-events: none;
}
.aurora {
position: absolute;
border-radius: 50%;
filter: blur(60px);
opacity: 0.3;
will-change: transform;
}
.aurora-1 {
width: 100%;
height: 80vh;
background: radial-gradient(circle, var(--color-base) 0%, transparent 60%);
top: -20%;
left: -10%;
animation: drift 30s infinite alternate ease-in-out;
}
.aurora-2 {
width: 80%;
height: 60vh;
background: radial-gradient(circle, var(--shade-40) 0%, transparent 60%);
bottom: -10%;
right: -10%;
animation: drift 35s infinite alternate-reverse ease-in-out;
}
@keyframes drift {
from {
transform: translate(0, 0) scale(1);
}
to {
transform: translate(20px, 15px) scale(1.05);
}
}
.shell {
display: flex;
flex-direction: column;
height: 100%;
position: relative;
z-index: 10;
width: 100%;
}
.top-nav {
position: absolute;
top: 0;
left: 0;
right: 0;
padding: calc(8px + var(--safe-top)) 16px 8px 16px;
display: flex;
justify-content: space-between;
align-items: center;
z-index: 100;
background: linear-gradient(180deg, var(--shade-90) 0%, rgba(25, 2, 13, 0.5) 100%);
backdrop-filter: blur(8px);
height: calc(var(--header-height) + var(--safe-top));
}
.logo {
font-weight: 700;
font-size: 14px;
letter-spacing: -0.3px;
color: var(--tint-100);
}
button.circle-btn {
appearance: none;
-webkit-appearance: none;
width: 32px;
height: 32px;
border-radius: 50%;
background: rgba(255, 255, 255, 0.06);
border: 0.5px solid var(--border-dim);
display: flex;
align-items: center;
justify-content: center;
color: var(--tint-50);
transition: all 0.2s;
cursor: pointer;
padding: 0;
margin: 0;
}
button.circle-btn:hover {
background: rgba(255, 255, 255, 0.1);
color: var(--tint-80);
}
button.circle-btn:active {
background: rgba(255, 255, 255, 0.15);
transform: scale(0.96);
color: var(--tint-100);
}
button.circle-btn:focus-visible {
outline: 2px solid var(--color-base);
outline-offset: 2px;
}
.chat-stream {
flex: 1;
overflow-y: auto;
padding-top: calc(var(--header-height) + var(--safe-top) + 10px);
padding-bottom: 120px;
padding-left: 12px;
padding-right: 12px;
display: flex;
flex-direction: column;
gap: 16px;
scroll-behavior: smooth;
-webkit-overflow-scrolling: touch;
width: 100%;
}
.chat-stream::-webkit-scrollbar {
display: none;
}
.msg-container {
display: flex;
flex-direction: column;
max-width: 95%;
gap: 4px;
position: relative;
}
.msg-user {
align-self: flex-end;
align-items: flex-end;
}
.msg-assistant {
align-self: flex-start;
width: 100%;
align-items: flex-start;
}
.bubble {
padding: 10px 14px;
font-size: 14px;
line-height: 1.5;
border-radius: 18px;
position: relative;
word-wrap: break-word;
word-break: break-word;
max-width: 100%;
color: var(--text-main);
background: rgba(0, 0, 0, 0.12);
border: 0.5px solid rgba(255, 255, 255, 0.05);
}
.bubble-user {
background: var(--shade-80);
color: var(--tint-100);
border-bottom-right-radius: 4px;
border: 0.5px solid var(--shade-60);
}
.bubble-assistant {
background: rgba(19, 3, 12, 0.95);
border-bottom-left-radius: 4px;
}
.msg-tools {
opacity: 0;
transition: opacity 0.2s;
display: flex;
gap: 8px;
margin-top: 4px;
padding-left: 4px;
}
.msg-container:hover .msg-tools,
.msg-container:focus-within .msg-tools {
opacity: 1;
}
button.tool-btn {
background: none;
border: none;
padding: 4px;
cursor: pointer;
color: var(--shade-50);
border-radius: 4px;
display: flex;
align-items: center;
justify-content: center;
}
button.tool-btn:hover {
color: var(--color-base);
background: rgba(255, 255, 255, 0.05);
}
.code-box {
background: var(--shade-95);
border: 0.5px solid var(--shade-70);
border-radius: 8px;
margin: 8px 0;
overflow: hidden;
width: 100%;
}
.code-bar {
background: var(--shade-80);
padding: 6px 10px;
display: flex;
justify-content: space-between;
align-items: center;
border-bottom: 0.5px solid var(--shade-70);
gap: 8px;
}
.code-label {
font-size: 10px;
font-weight: 700;
font-family: "SF Mono", monospace;
color: var(--tint-50);
white-space: nowrap;
}
.code-actions {
display: flex;
align-items: center;
gap: 4px;
}
.code-view {
padding: 8px 10px 10px 10px;
overflow-x: auto;
display: block;
}
.code-view pre {
font-family: "SF Mono", "Menlo", monospace;
font-size: 12px;
line-height: 1.5;
color: var(--tint-80);
margin: 0;
}
.code-box.collapsed .code-view {
display: none;
}
.dock-ui {
position: absolute;
bottom: 0;
left: 0;
width: 100%;
padding: 0 12px calc(12px + var(--safe-bottom)) 12px;
z-index: 200;
display: flex;
justify-content: center;
pointer-events: none;
background: linear-gradient(0deg, var(--shade-90) 0%, transparent 100%);
}
.pill-input {
pointer-events: auto;
width: 100%;
max-width: 600px;
min-height: 48px;
background: var(--surface-glass);
backdrop-filter: blur(20px) saturate(180%);
border: 0.5px solid rgba(255, 255, 255, 0.15);
border-radius: 24px;
display: flex;
align-items: flex-end;
padding: 6px 8px;
gap: 8px;
box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
transition: border-color 0.2s;
position: relative;
}
.pill-input:focus-within {
border-color: var(--shade-40);
background: #1e0310;
}
button.icon-btn {
appearance: none;
border: none;
background: transparent;
width: 34px;
height: 34px;
border-radius: 50%;
display: flex;
align-items: center;
justify-content: center;
color: var(--tint-50);
cursor: pointer;
transition: 0.2s;
margin-bottom: 2px;
flex-shrink: 0;
}
button.icon-btn:hover {
color: var(--tint-100);
background: rgba(255, 255, 255, 0.05);
}
button.icon-btn:disabled {
opacity: 0.5;
cursor: not-allowed;
}
textarea.input-el {
flex: 1;
background: transparent;
border: none;
outline: none;
color: var(--tint-100);
font-size: 16px;
line-height: 22px;
padding: 7px 4px;
resize: none;
overflow-y: hidden;
max-height: 120px;
min-height: 24px;
font-family: inherit;
}
textarea.input-el::placeholder {
color: var(--shade-50);
}
button.send-btn {
appearance: none;
border: none;
width: 34px;
height: 34px;
border-radius: 50%;
background: rgba(255, 255, 255, 0.06);
display: flex;
align-items: center;
justify-content: center;
color: rgba(255, 255, 255, 0.2);
transition: 0.3s;
cursor: pointer;
margin-bottom: 2px;
flex-shrink: 0;
}
button.send-btn.ready {
background: var(--tint-100);
color: var(--shade-90);
}
.quick-menu {
position: absolute;
bottom: 60px;
right: 4px;
background: rgba(25, 2, 13, 0.97);
border-radius: 12px;
border: 1px solid var(--shade-70);
padding: 6px 8px;
min-width: 190px;
box-shadow: 0 12px 30px rgba(0, 0, 0, 0.7);
display: none;
z-index: 300;
}
.quick-menu.open {
display: block;
}
.quick-menu-label {
font-size: 10px;
text-transform: uppercase;
letter-spacing: 0.1em;
color: var(--shade-40);
margin-bottom: 4px;
}
.quick-menu-item {
display: flex;
align-items: center;
justify-content: space-between;
gap: 12px;
padding: 6px 4px;
color: var(--tint-80);
font-size: 12px;
}
.quick-menu-toggle {
position: relative;
width: 32px;
height: 18px;
border-radius: 999px;
background: rgba(255, 255, 255, 0.08);
border: 1px solid rgba(255, 255, 255, 0.18);
display: flex;
align-items: center;
padding: 2px;
}
.quick-menu-toggle input {
opacity: 0;
position: absolute;
inset: 0;
margin: 0;
cursor: pointer;
}
.quick-menu-knob {
width: 14px;
height: 14px;
border-radius: 999px;
background: var(--shade-70);
transform: translateX(0);
transition: transform 0.2s, background 0.2s;
pointer-events: none;
}
.quick-menu-toggle input:checked + .quick-menu-knob {
transform: translateX(14px);
background: var(--tint-40);
}
.sidebar {
position: fixed;
top: 0;
left: 0;
bottom: 0;
width: 280px;
background: var(--shade-95);
border-right: 1px solid var(--shade-80);
transform: translateX(-100%);
transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
z-index: 300;
padding-top: calc(20px + var(--safe-top));
display: flex;
flex-direction: column;
}
.sidebar.open {
transform: translateX(0);
box-shadow: 20px 0 50px rgba(0, 0, 0, 0.5);
}
.scrim {
position: fixed;
inset: 0;
background: rgba(0, 0, 0, 0.6);
opacity: 0;
pointer-events: none;
transition: opacity 0.3s;
z-index: 290;
backdrop-filter: blur(2px);
}
.scrim.open {
opacity: 1;
pointer-events: auto;
}
button.sidebar-item {
appearance: none;
background: none;
border: none;
width: 100%;
text-align: left;
padding: 12px 20px;
color: var(--tint-60);
display: flex;
align-items: center;
gap: 12px;
cursor: pointer;
transition: 0.2s;
border-bottom: 1px solid var(--shade-80);
}
button.sidebar-item:hover {
color: var(--tint-100);
background: var(--shade-80);
}
.report {
position: fixed;
inset: 0;
background: var(--shade-90);
z-index: 500;
transform: translateY(100%);
transition: transform 0.4s cubic-bezier(0.19, 1, 0.22, 1);
display: flex;
flex-direction: column;
}
.report.visible {
transform: translateY(0);
}
.report-header {
flex-shrink: 0;
display: flex;
justify-content: space-between;
align-items: center;
padding: calc(10px + var(--safe-top)) 16px 12px 16px;
background: var(--shade-95);
border-bottom: 1px solid var(--shade-80);
}
.reasoning-toggle {
margin-top: 6px;
font-size: 11px;
color: var(--tint-60);
background: none;
border: none;
padding: 0;
display: inline-flex;
align-items: center;
gap: 4px;
cursor: pointer;
}
.reasoning-box {
margin-top: 6px;
padding: 8px 10px;
border-radius: 8px;
background: rgba(255, 255, 255, 0.03);
border: 0.5px solid var(--shade-80);
font-size: 12px;
line-height: 1.5;
display: none;
color: var(--tint-80);
}
#splash {
transition: opacity 0.25s;
}
</style>
</head>
<body>
<div class="ambient-layer">
<div class="aurora aurora-1"></div>
<div class="aurora aurora-2"></div>
</div>
<div class="shell">
<header class="top-nav">
<button type="button" class="circle-btn" id="menu-btn" aria-label="Menü megnyitása">
<i data-lucide="menu" width="18"></i>
</button>
<div class="logo">TiffyTime</div>
<div style="width:32px;height:32px"></div>
</header>
<main class="chat-stream" id="chat" role="log" aria-live="polite">
<div class="flex flex-col items-center justify-center h-full opacity-40" id="splash">
<h1 class="text-2xl font-light tracking-wide select-none" style="color: var(--tint-60);">TiffyTime</h1>
</div>
</main>
<div class="dock-ui">
<div class="pill-input">
<button type="button" class="icon-btn" id="file-upload" aria-label="Fájl feltöltése">
<i data-lucide="paperclip" width="18"></i>
</button>
<button type="button" class="icon-btn" id="more-btn" aria-label="További lehetőségek">
<i data-lucide="plus" width="18"></i>
</button>
<textarea class="input-el" id="input" placeholder="Írj egy üzenetet..." rows="1" aria-label="Üzenet írása"></textarea>
<button type="button" class="send-btn" id="send-btn" aria-label="Küldés">
<i data-lucide="arrow-up" width="20" stroke-width="2.5"></i>
</button>
<div class="quick-menu" id="quick-menu" aria-hidden="true">
<div class="quick-menu-label">Beállítások</div>
<div class="quick-menu-item">
<span>Webes keresés</span>
<label class="quick-menu-toggle">
<input type="checkbox" id="search-toggle">
<span class="quick-menu-knob"></span>
</label>
</div>
</div>
</div>
</div>
</div>
<div class="scrim" id="scrim" aria-hidden="true"></div>
<aside class="sidebar" id="sidebar" aria-hidden="true">
<div class="px-5 pt-4 pb-2">
<div class="text-[10px] font-bold uppercase tracking-widest mb-4" style="color: var(--shade-40);">Műveletek</div>
</div>
<button type="button" class="sidebar-item" id="new-chat">
<i data-lucide="plus-circle" width="18"></i>
<span class="text-sm font-medium">Új beszélgetés</span>
</button>
</aside>
<div class="report" id="report" aria-hidden="true">
<div class="report-header">
<button type="button" class="icon-btn" id="close-report" aria-label="Bezárás">
<i data-lucide="chevron-down" width="22"></i>
</button>
<span class="text-[10px] font-bold uppercase tracking-widest" style="color: var(--color-base);">Jelentés</span>
<button type="button" class="icon-btn" id="share-report" aria-label="Megosztás">
<i data-lucide="share" width="18"></i>
</button>
</div>
<div id="report-content" class="p-6 overflow-y-auto flex-1 pb-20 text-sm leading-relaxed" style="color: var(--tint-90);"></div>
</div>
<script>
const App = (function() {
const API_URL = window.location.origin;
const state = {
sending: false,
controller: null,
animationFrameId: null,
intervalId: null
};
let conversationHistory = [];
let sessionId = getSessionId();
const ui = {
input: document.getElementById("input"),
chat: document.getElementById("chat"),
send: document.getElementById("send-btn"),
splash: document.getElementById("splash"),
sidebar: document.getElementById("sidebar"),
scrim: document.getElementById("scrim"),
menuBtn: document.getElementById("menu-btn"),
report: document.getElementById("report"),
closeReportBtn: document.getElementById("close-report"),
reportContent: document.getElementById("report-content"),
fileBtn: document.getElementById("file-upload"),
newChatBtn: document.getElementById("new-chat"),
shareReportBtn: document.getElementById("share-report"),
moreBtn: document.getElementById("more-btn"),
quickMenu: document.getElementById("quick-menu"),
searchToggle: document.getElementById("search-toggle")
};
function getSessionId() {
let id = localStorage.getItem("tiffysessv2");
if (!id) {
if (typeof crypto !== "undefined" && crypto.randomUUID) {
id = crypto.randomUUID();
} else {
id = "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, function(c) {
var r = Math.random() * 16 | 0;
var v = c === "x" ? r : (r & 0x3 | 0x8);
return v.toString(16);
});
}
localStorage.setItem("tiffysessv2", id);
}
return id;
}
function escapeHtml(str) {
if (!str) return "";
return String(str).replace(/[&<>"']/g, function(m) {
return {"&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;", "'": "&#39;"}[m];
});
}
function setBusy(isBusy) {
state.sending = isBusy;
ui.input.disabled = isBusy;
ui.fileBtn.disabled = isBusy;
ui.send.disabled = isBusy;
ui.moreBtn.disabled = isBusy;
if (isBusy) {
ui.send.classList.remove("ready");
ui.send.style.opacity = "0.5";
} else {
ui.send.style.opacity = "1";
updateSendBtnState();
}
setTimeout(function() {
ui.input.focus();
}, 50);
}
function updateSendBtnState() {
if (state.sending) return;
const val = ui.input.value.trim();
ui.send.className = val ? "send-btn ready" : "send-btn";
}
function adjustTextareaHeight() {
ui.input.style.height = "auto";
const newHeight = Math.min(ui.input.scrollHeight, 120);
ui.input.style.height = newHeight + "px";
ui.input.style.overflowY = newHeight >= 120 ? "auto" : "hidden";
}
function createCodeBlock(lang, code) {
const safeLang = escapeHtml(lang || "text");
const safeCode = escapeHtml(code);
const boxId = "box-" + Math.random().toString(36).slice(2, 9);
const codeId = "code-" + Math.random().toString(36).slice(2, 9);
const lineCount = code.split("\n").length;
const label = safeLang + " · " + lineCount + " sor";
return "<div class=\"code-box collapsed\" id=\"" + boxId + "\"><div class=\"code-bar\"><span class=\"code-label\">" + label + "</span><div class=\"code-actions\"><button type=\"button\" class=\"tool-btn\" onclick=\"App.copyCode('" + codeId + "', this)\" aria-label=\"Kód másolása\"><i data-lucide=\"copy\" width=\"14\"></i></button><button type=\"button\" class=\"tool-btn\" onclick=\"App.toggleCodeBlock('" + boxId + "', this)\" aria-label=\"Kód megnyitása\" aria-expanded=\"false\"><i data-lucide=\"chevron-down\" width=\"14\"></i></button></div></div><div class=\"code-view\"><pre><code id=\"" + codeId + "\">" + safeCode + "</code></pre></div></div>";
}
function formatMessage(text) {
const codeRegex = /```(\w*)\n([\s\S]*?)```/g;
let formatted = "";
let lastIndex = 0;
let match;
while ((match = codeRegex.exec(text)) !== null) {
const preText = text.slice(lastIndex, match.index);
if (preText) {
formatted += escapeHtml(preText).replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>").replace(/\n/g, "<br>");
}
formatted += createCodeBlock(match[1], match[2]);
lastIndex = codeRegex.lastIndex;
}
const postText = text.slice(lastIndex);
if (postText) {
formatted += escapeHtml(postText).replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>").replace(/\n/g, "<br>");
}
return formatted;
}
function appendMessage(role, text, reasoning) {
const container = document.createElement("div");
container.className = "msg-container msg-" + role;
const bubble = document.createElement("div");
bubble.className = "bubble bubble-" + role;
bubble.innerHTML = formatMessage(text);
container.appendChild(bubble);
if (role === "assistant") {
const tools = document.createElement("div");
tools.className = "msg-tools";
const copyBtn = document.createElement("button");
copyBtn.type = "button";
copyBtn.className = "tool-btn";
copyBtn.setAttribute("aria-label", "Üzenet másolása");
copyBtn.innerHTML = "<i data-lucide=\"copy\" width=\"14\"></i>";
copyBtn.onclick = function() {
copyText(text);
};
tools.appendChild(copyBtn);
container.appendChild(tools);
if (reasoning && reasoning.trim().length > 0) {
const toggle = document.createElement("button");
toggle.type = "button";
toggle.className = "reasoning-toggle";
toggle.textContent = "Gondolatmenet megjelenítése";
const box = document.createElement("div");
box.className = "reasoning-box";
box.innerHTML = formatMessage(reasoning);
let open = false;
toggle.onclick = function() {
open = !open;
box.style.display = open ? "block" : "none";
toggle.textContent = open ? "Gondolatmenet elrejtése" : "Gondolatmenet megjelenítése";
};
container.appendChild(toggle);
container.appendChild(box);
}
}
ui.chat.appendChild(container);
requestAnimationFrame(function() {
ui.chat.scrollTo({
top: ui.chat.scrollHeight,
behavior: "smooth"
});
});
lucide.createIcons();
}
async function copyText(text) {
try {
if (navigator.clipboard) {
await navigator.clipboard.writeText(text);
}
} catch (e) {
}
}
async function streamResponse(userQuery) {
setBusy(true);
const container = document.createElement("div");
container.className = "msg-container msg-assistant";
const bubble = document.createElement("div");
bubble.className = "bubble bubble-assistant";
container.appendChild(bubble);
ui.chat.appendChild(container);
ui.chat.scrollTop = ui.chat.scrollHeight;
let fullText = "";
let reasoningText = "";
state.controller = new AbortController();
const timeoutId = setTimeout(function() {
if (state.controller) {
state.controller.abort();
}
}, 45000);
try {
const response = await fetch(API_URL + "/chat", {
method: "POST",
headers: {
"Content-Type": "application/json"
},
body: JSON.stringify({
message: userQuery,
sessionid: sessionId,
usedeep: false,
enable_search: ui.searchToggle && ui.searchToggle.checked
}),
signal: state.controller.signal
});
clearTimeout(timeoutId);
if (!response.ok) {
throw new Error("HTTP " + response.status);
}
const reader = response.body.getReader();
const decoder = new TextDecoder();
let buffer = "";
try {
for (;;) {
const readResult = await reader.read();
if (readResult.done) {
break;
}
buffer += decoder.decode(readResult.value, {
stream: true
});
const lines = buffer.split("\n");
