_rate_lock = threading.Lock()
_rate_store: Dict[str, List[float]] = {}

def _now() -> float:
    return time.time()

def _safe_str(v: Any) -> str:
    return v if isinstance(v, str) else ""

def _trim(s: str, limit: int) -> str:
    if len(s) <= limit:
        return s
    return s[:limit]

def sanitize_text(value: Any, limit: int) -> str:
    s = _safe_str(value)
    if not s:
        return ""
    s = s.strip()
    if not s:
        return ""
    return _trim(s, limit)

def parse_bool(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        return value.strip().lower() in {"1", "true", "yes", "y", "on"}
    if isinstance(value, (int, float)):
        return value != 0
    return False

def validate_date_yyyy_mm_dd(date_str: Any) -> Optional[str]:
    if not isinstance(date_str, str):
        return None
    s = date_str.strip()
    if not s:
        return None
    try:
        datetime.strptime(s, "%Y-%m-%d")
        return s
    except ValueError:
        return None

def _get_client_ip() -> str:
    xfwd = request.headers.get("X-Forwarded-For", "")
    if xfwd:
        ip = xfwd.split(",")[0].strip()
        if ip:
            return ip
    xreal = request.headers.get("X-Real-IP", "").strip()
    if xreal:
        return xreal
    return request.environ.get("REMOTE_ADDR", "").strip() or "unknown"

def check_rate_limit(key: str) -> bool:
    if RATE_LIMIT_REQUESTS <= 0:
        return True
    now = _now()
    cutoff = now - float(RATE_LIMIT_WINDOW_SECONDS)
    with _rate_lock:
        times = _rate_store.get(key)
        if times is None:
            if len(_rate_store) >= RATE_LIMIT_MAX_KEYS:
                _rate_store.clear()
            _rate_store[key] = [now]
            return True
        i = 0
        n = len(times)
        while i < n and times[i] < cutoff:
            i += 1
        if i > 0:
            del times[:i]
        if len(times) >= RATE_LIMIT_REQUESTS:
            return False
        times.append(now)
        return True

def _constant_time_eq(a: str, b: str) -> bool:
    return hmac.compare_digest(a.encode("utf-8"), b.encode("utf-8"))

def _require_auth() -> Optional[Response]:
    if SECRET_API_KEY is None:
        return None
    secret = SECRET_API_KEY.strip()
    if not secret:
        return None
    auth_header = request.headers.get("Authorization", "")
    expected = f"Bearer {secret}"
    if not _constant_time_eq(auth_header, expected):
        logger.warning("Unauthorized request ip=%s", _get_client_ip())
        return Response("Unauthorized", status=401, mimetype="text/plain", headers={"WWW-Authenticate": "Bearer"})
    return None

def _parse_json_body() -> Tuple[Optional[Dict[str, Any]], Optional[Response]]:
    if request.method == "OPTIONS":
