def _validate_history(raw: Any) -> List[Dict[str, str]]:
    history: List[Dict[str, str]] = []
    if not isinstance(raw, list):
        return history
    total_chars = 0
    for msg in raw[:MAX_HISTORY_MESSAGES]:
        if not isinstance(msg, dict):
            continue
        role = msg.get("role")
        if role not in {"user", "assistant"}:
            continue
        content = sanitize_text(msg.get("content", ""), MAX_MESSAGE_CHARS)
        if not content:
            continue
        total_chars += len(content)
        if total_chars > MAX_HISTORY_TOTAL_CHARS:
            break
        history.append({"role": role, "content": content})
    return history

def _normalize_domains(domains: Any) -> Optional[List[str]]:
    if not isinstance(domains, list):
        return None
    out: List[str] = []
    for d in domains:
        if not isinstance(d, str):
            continue
        s = d.strip().lower()
        if not s:
            continue
        if "://" in s:
            parts = s.split("://", 1)
            if len(parts) == 2:
                s = parts[1]
        s = s.split("/", 1)[0]
        if not s:
            continue
        out.append(s)
    return out or None

def _normalize_text_filter(values: Any) -> Optional[List[str]]:
    if not isinstance(values, list) or not values:
        return None
    v = values[0]
    if not isinstance(v, str):
        return None
    s = " ".join(v.strip().split())
    if not s:
        return None
    if len(s.split()) > 5:
        return None
    return [s]

def search_web_exa(
    queries: List[str],
    search_type: str = "auto",
    include_domains: Optional[List[str]] = None,
    exclude_domains: Optional[List[str]] = None,
    start_published_date: Optional[str] = None,
    end_published_date: Optional[str] = None,
    category: Optional[str] = None,
    include_text: Optional[List[str]] = None,
    exclude_text: Optional[List[str]] = None,
) -> Dict[str, Any]:
    if not isinstance(queries, list):
        return {"total_results": 0, "results": [{"error": "Queries must be a list"}]}
    cleaned: List[str] = []
    seen_q: set = set()
    for q in queries[:EXA_MAX_QUERIES]:
        if not isinstance(q, str):
            continue
        s = " ".join(q.strip().split())
        if not s:
            continue
        key = s.lower()
        if key in seen_q:
            continue
        seen_q.add(key)
        cleaned.append(s)
    if not cleaned:
        return {"total_results": 0, "results": [{"error": "No valid queries"}]}
    st = search_type if isinstance(search_type, str) else "auto"
    st = st.strip().lower()
    if st not in _ALLOWED_SEARCH_TYPES:
        st = "auto"
    cat = category if isinstance(category, str) else None
    if cat is not None:
        cat = cat.strip()
        if cat not in _ALLOWED_CATEGORIES:
            cat = None
    sp = validate_date_yyyy_mm_dd(start_published_date)
    ep = validate_date_yyyy_mm_dd(end_published_date)
    inc_dom = _normalize_domains(include_domains)
    exc_dom = _normalize_domains(exclude_domains)
    inc_txt = _normalize_text_filter(include_text)
    exc_txt = _normalize_text_filter(exclude_text)
    results: List[Dict[str, Any]] = []
    seen_urls: set = set()
    for q in cleaned:
        params: Dict[str, Any] = {
            "query": q,
            "num_results": EXA_RESULTS_PER_QUERY,
            "type": st,
            "text": True,
            "highlights": True,
            "use_autoprompt": True,
        }
        if inc_dom:
            params["include_domains"] = inc_dom
        if exc_dom:
            params["exclude_domains"] = exc_dom
        if sp:
            params["start_published_date"] = sp
        if ep:
            params["end_published_date"] = ep
        if cat:
            params["category"] = cat
        if inc_txt:
            params["include_text"] = inc_txt
        if exc_txt:
            params["exclude_text"] = exc_txt
        try:
            resp = exa_client.search_and_contents(**params)
            items = getattr(resp, "results", None)
            if not isinstance(items, list):
                continue
            for item in items:
                url = sanitize_text(getattr(item, "url", ""), 4000)
                if url:
                    if url in seen_urls:
                        continue
                    seen_urls.add(url)
                title = sanitize_text(getattr(item, "title", ""), 2000)
                text_val = getattr(item, "text", "")
                text = text_val if isinstance(text_val, str) else ""
                highlights_out: List[str] = []
                hs = getattr(item, "highlights", None)
                if isinstance(hs, list):
                    for h in hs[:10]:
                        if isinstance(h, str):
                            hh = sanitize_text(h, 4000)
                            if hh:
                                highlights_out.append(hh)
                published_date = getattr(item, "published_date", None)
                author = getattr(item, "author", None)
                results.append(
                    {
                        "query": q,
                        "title": title,
                        "url": url,
                        "published_date": published_date if isinstance(published_date, str) else None,
                        "author": author if isinstance(author, str) else None,
                        "text": text,
                        "highlights": highlights_out,
                    }
                )
        except Exception as e:
            logger.error("Search failed query=%s err=%s", sanitize_text(q, 500), sanitize_text(str(e), 2000))
            results.append({"query": q, "error": "Search failed"})
    return {"total_results": len(results), "results": results}

def _sse_event(payload: Dict[str, Any]) -> str:
    return f"data: {json.dumps(payload, ensure_ascii=False)}\n\n"

def _iter_stream(stream: Iterable[Any]) -> Iterable[Any]:
    for chunk in stream:
        yield chunk

def _extract_delta(choice: Any) -> Any:
    return getattr(choice, "delta", None)

def _extract_finish_reason(choice: Any) -> Optional[str]:
    fr = getattr(choice, "finish_reason", None)
    return fr if isinstance(fr, str) else None

def _collect_tool_calls_from_delta(delta: Any, buffer: Dict[int, Dict[str, Any]]) -> None:
    tool_calls = getattr(delta, "tool_calls", None)
    if not tool_calls:
        return
    for tc in tool_calls:
        idx = getattr(tc, "index", 0)
        if not isinstance(idx, int):
            idx = 0
        if idx not in buffer:
            buffer[idx] = {
                "id": sanitize_text(getattr(tc, "id", ""), 300),
                "type": sanitize_text(getattr(tc, "type", "function"), 50) or "function",
                "function": {"name": "", "arguments": ""},
            }
        func = getattr(tc, "function", None)
        if func is None:
            continue
        name = getattr(func, "name", None)
        if isinstance(name, str) and name.strip():
            buffer[idx]["function"]["name"] = name.strip()
        args = getattr(func, "arguments", None)
        if isinstance(args, str) and args:
            cur = buffer[idx]["function"]["arguments"]
            if isinstance(cur, str):
                if len(cur) + len(args) <= 4000000:
                    buffer[idx]["function"]["arguments"] = cur + args

def _execute_tool_call(name: str, args_json: str) -> Tuple[Dict[str, Any], str]:
    if name != "search_web_exa":
        return {"error": "Unknown tool"}, "tool_unknown"
    try:
        obj = json.loads(args_json) if args_json else {}
    except json.JSONDecodeError:
        return {"error": "Invalid tool arguments"}, "tool_bad_args"
    if not isinstance(obj, dict):
        return {"error": "Invalid tool arguments"}, "tool_bad_args"
    queries = obj.get("queries", [])
    st = obj.get("search_type", obj.get("type", "auto"))
    include_domains = obj.get("include_domains", obj.get("includeDomains"))
    exclude_domains = obj.get("exclude_domains", obj.get("excludeDomains"))
    start_pd = obj.get("start_published_date", obj.get("startPublishedDate"))
    end_pd = obj.get("end_published_date", obj.get("endPublishedDate"))
    category = obj.get("category")
    include_text = obj.get("include_text")
    exclude_text = obj.get("exclude_text")
    res = search_web_exa(
        queries=queries,
        search_type=st,
        include_domains=include_domains,
        exclude_domains=exclude_domains,
        start_published_date=start_pd,
        end_published_date=end_pd,
        category=category,
        include_text=include_text,
        exclude_text=exclude_text,
    )
    return res, "tool_ok"

@app.after_request
def add_headers(response: Response) -> Response:
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["X-Frame-Options"] = "DENY"
    response.headers["Referrer-Policy"] = "strict-origin-when-cross-origin"
    response.headers["Access-Control-Allow-Origin"] = "*"
    response.headers["Access-Control-Allow-Methods"] = "POST, OPTIONS"
    response.headers["Access-Control-Allow-Headers"] = "Content-Type, Authorization"
