@app.route("/chat", methods=["POST", "OPTIONS"])
def chat() -> Response:
    if request.method == "OPTIONS":
        return Response("", status=204)
    ip = _get_client_ip()
    if not check_rate_limit(ip):
        return Response("Rate limit exceeded", status=429, mimetype="text/plain", headers={"Retry-After": str(RATE_LIMIT_WINDOW_SECONDS)})
    auth_resp = _require_auth()
    if auth_resp is not None:
        return auth_resp
    data, err = _parse_json_body()
    if err is not None:
        return err
    assert data is not None
    user_message = sanitize_text(data.get("message", ""), MAX_MESSAGE_CHARS)
    if not user_message:
        return Response("Message required", status=400, mimetype="text/plain")
    enable_search = parse_bool(data.get("enable_search", False))
    history = _validate_history(data.get("history", []))
    system_prompt = SYSTEM_PROMPT_SEARCH if enable_search else SYSTEM_PROMPT_NOSEARCH
    base_messages: List[Dict[str, Any]] = [{"role": "system", "content": system_prompt}]
    base_messages.extend(history)
    base_messages.append({"role": "user", "content": user_message})

    def generate() -> Generator[str, None, None]:
        yield _sse_event({"type": "info", "content": "connected"})
        current_messages: List[Dict[str, Any]] = list(base_messages)
        for _turn in range(max(1, min(MAX_TURNS, 50))):
            tool_calls_buffer: Dict[int, Dict[str, Any]] = {}
            try:
                params: Dict[str, Any] = {
                    "messages": current_messages,
                    "model": MODEL_NAME,
                    "stream": True,
                    "max_completion_tokens": MAX_COMPLETION_TOKENS,
                    "temperature": TEMPERATURE,
                    "top_p": TOP_P,
                }
