                    params["tools"] = TOOLS
                    params["tool_choice"] = "auto"
                    params["parallel_tool_calls"] = True
                stream = cerebras_client.chat.completions.create(**params)
                finished = False
                for chunk in _iter_stream(stream):
                    choices = getattr(chunk, "choices", None)
                    if not isinstance(choices, list) or not choices:
                        continue
                    choice0 = choices[0]
                    delta = _extract_delta(choice0)
                    if delta is not None:
                        reasoning = getattr(delta, "reasoning", None)
                        if isinstance(reasoning, str) and reasoning:
                            yield _sse_event({"type": "reasoning", "content": reasoning})
                        content = getattr(delta, "content", None)
                        if isinstance(content, str) and content:
                            yield _sse_event({"type": "content", "content": content})
                        _collect_tool_calls_from_delta(delta, tool_calls_buffer)
                    fr = _extract_finish_reason(choice0)
                    if fr == "tool_calls":
                        break
                    if fr is not None:
                        finished = True
                        yield "data: [DONE]\n\n"
                        return
                if finished:
                    return
                if not tool_calls_buffer:
                    yield "data: [DONE]\n\n"
                    return
                yield _sse_event({"type": "info", "content": f"🔍 Keresés/eszköz hívás végrehajtása... ({len(tool_calls_buffer)})"})
                ordered = [tool_calls_buffer[k] for k in sorted(tool_calls_buffer.keys())]
                assistant_tool_calls: List[Dict[str, Any]] = []
                tool_messages: List[Dict[str, Any]] = []
                for tc in ordered:
                    tc_id = sanitize_text(tc.get("id", ""), 300)
                    tc_type = sanitize_text(tc.get("type", "function"), 50) or "function"
                    fn = tc.get("function", {}) if isinstance(tc.get("function", {}), dict) else {}
                    fn_name = sanitize_text(fn.get("name", ""), 200)
                    fn_args = fn.get("arguments", "")
                    if not isinstance(fn_args, str):
                        fn_args = ""
                    if not fn_name:
                        fn_name = "unknown"
                    assistant_tool_calls.append({"id": tc_id, "type": tc_type, "function": {"name": fn_name, "arguments": fn_args}})
                current_messages.append({"role": "assistant", "content": "", "tool_calls": assistant_tool_calls})
                for tc in ordered:
                    tc_id = sanitize_text(tc.get("id", ""), 300)
                    fn = tc.get("function", {}) if isinstance(tc.get("function", {}), dict) else {}
                    fn_name = sanitize_text(fn.get("name", ""), 200)
                    fn_args = fn.get("arguments", "")
                    if not isinstance(fn_args, str):
                        fn_args = ""
                    result_obj, status = _execute_tool_call(fn_name, fn_args)
                    tool_messages.append(
                        {
                            "role": "tool",
                            "tool_call_id": tc_id,
                            "content": json.dumps(result_obj, ensure_ascii=False),
                        }
                    )
                    if status == "tool_ok":
                        total = result_obj.get("total_results", 0) if isinstance(result_obj, dict) else 0
                        yield _sse_event({"type": "info", "content": f"✅ Keresés kész: {fn_name} ({total} elem)"})
                    else:
                        yield _sse_event({"type": "info", "content": f"⚠️ Tool hiba: {fn_name}"})
                current_messages.extend(tool_messages)
                continue
            except GeneratorExit:
                return
            except Exception as e:
                logger.error("Stream error ip=%s err=%s", ip, sanitize_text(str(e), 4000))
                yield _sse_event({"type": "error", "content": "Hiba történt a feldolgozás során."})
                yield "data: [DONE]\n\n"
                return
        yield "data: [DONE]\n\n"

    return Response(
        stream_with_context(generate()),
        mimetype="text/event-stream; charset=utf-8",
        headers={"Cache-Control": "no-cache", "Connection": "keep-alive", "X-Accel-Buffering": "no"},
    )

if __name__ == "__main__":
    port = int(os.environ.get("PORT", "5000"))
    app.run(host="0.0.0.0", port=port, debug=False)
